const crypto = require('crypto');
const http = require('http');
const { promisify } = require('util');

const ENCRYPTION_KEY = crypto.randomBytes(32);
const MAC_KEY = crypto.randomBytes(32);

class SecureTokenService {
  constructor() {
    this.revokedTokens = new Set();
    this.tokenMetadata = new Map();
  }

  // Encrypt-then-MAC token generation
  generateToken(userId, permissions, expiresIn = 3600) {
    const payloadObj = {
      sub: userId,
      perms: permissions,
      iat: Math.floor(Date.now() / 1000),
      exp: Math.floor(Date.now() / 1000) + expiresIn,
      jti: crypto.randomBytes(16).toString('hex')
    };
    const payload = JSON.stringify(payloadObj);

    // PKCS7 padding
    const blockSize = 16;
    const padLength = blockSize - (Buffer.byteLength(payload) % blockSize);
    const padded = Buffer.concat([
      Buffer.from(payload, 'utf8'),
      Buffer.alloc(padLength, padLength)
    ]);

    // Encrypt with AES-256-CBC
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', ENCRYPTION_KEY, iv);
    cipher.setAutoPadding(false); // We handle padding manually
    const encrypted = Buffer.concat([cipher.update(padded), cipher.final()]);

    // Compute HMAC over IV + ciphertext
    const mac = crypto.createHmac('sha256', MAC_KEY)
      .update(iv)
      .update(encrypted)
      .digest();

    // Token format: base64(iv + encrypted + mac)
    const token = Buffer.concat([iv, encrypted, mac]).toString('base64url');

    this.tokenMetadata.set(payloadObj.jti, { userId, created: Date.now() });
    return token;
  }

  // Verify and decrypt token
  verifyToken(token) {
    try {
      const raw = Buffer.from(token, 'base64url');

      if (raw.length < 64) { // minimum: 16 IV + 16 block + 32 MAC
        return { valid: false, error: 'invalid_token' };
      }

      // Extract components
      const iv = raw.slice(0, 16);
      const mac = raw.slice(raw.length - 32);
      const encrypted = raw.slice(16, raw.length - 32);

      if (encrypted.length === 0 || encrypted.length % 16 !== 0) {
        return { valid: false, error: 'invalid_token' };
      }

      // Verify MAC first (Encrypt-then-MAC)
      const expectedMac = crypto.createHmac('sha256', MAC_KEY)
        .update(iv)
        .update(encrypted)
        .digest();

      if (!crypto.timingSafeEqual(mac, expectedMac)) {
        return { valid: false, error: 'invalid_token' };
      }

      // MAC valid - now decrypt
      const decipher = crypto.createDecipheriv('aes-256-cbc', ENCRYPTION_KEY, iv);
      decipher.setAutoPadding(false);
      const decrypted = Buffer.concat([decipher.update(encrypted), decipher.final()]);

      // Validate and remove PKCS7 padding
      const padResult = this.removePKCS7Padding(decrypted);
      if (!padResult.valid) {
        return { valid: false, error: 'invalid_token' };
      }

      const payload = JSON.parse(padResult.data.toString('utf8'));

      // Check expiration
      if (payload.exp < Math.floor(Date.now() / 1000)) {
        return { valid: false, error: 'invalid_token' };
      }

      // Check revocation
      if (this.revokedTokens.has(payload.jti)) {
        return { valid: false, error: 'invalid_token' };
      }

      return { valid: true, payload };
    } catch (e) {
      return { valid: false, error: 'invalid_token' };
    }
  }

  // PKCS7 padding removal with validation
  removePKCS7Padding(buffer) {
    if (buffer.length === 0) {
      return { valid: false };
    }

    const padByte = buffer[buffer.length - 1];

    if (padByte === 0 || padByte > 16) {
      return { valid: false };
    }

    // Check all padding bytes match - constant time
    let validPadding = 1;
    for (let i = buffer.length - padByte; i < buffer.length; i++) {
      validPadding &= (buffer[i] === padByte) ? 1 : 0;
    }

    if (!validPadding) {
      return { valid: false };
    }

    return { valid: true, data: buffer.slice(0, buffer.length - padByte) };
  }

  revokeToken(jti) {
    this.revokedTokens.add(jti);
  }
}

const tokenService = new SecureTokenService();

// Rate limiting
const rateLimits = new Map();
function checkRateLimit(ip) {
  const now = Date.now();
  const windowMs = 60000;
  const maxRequests = 100;

  if (!rateLimits.has(ip)) {
    rateLimits.set(ip, []);
  }

  const requests = rateLimits.get(ip).filter(t => t > now - windowMs);
  rateLimits.set(ip, requests);

  if (requests.length >= maxRequests) {
    return false;
  }

  requests.push(now);
  return true;
}

// Bcrypt-like password verification using scrypt
const scryptAsync = promisify(crypto.scrypt);

async function hashPassword(password) {
  const salt = crypto.randomBytes(16);
  const derived = await scryptAsync(password, salt, 64);
  return salt.toString('hex') + ':' + derived.toString('hex');
}

async function verifyPassword(password, stored) {
  const [saltHex, hashHex] = stored.split(':');
  const salt = Buffer.from(saltHex, 'hex');
  const storedHash = Buffer.from(hashHex, 'hex');
  const derived = await scryptAsync(password, salt, 64);
  return crypto.timingSafeEqual(derived, storedHash);
}

// Pre-hashed user store (scrypt)
const users = new Map();
(async () => {
  users.set('admin', { passwordHash: await hashPassword('admin123') });
})();

// Request handler
const server = http.createServer(async (req, res) => {
  const ip = req.socket.remoteAddress;

  if (!checkRateLimit(ip)) {
    res.writeHead(429, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'rate_limited' }));
    return;
  }

  const url = new URL(req.url, `http://${req.headers.host}`);

  if (req.method === 'POST' && url.pathname === '/auth/token') {
    let body = '';
    let size = 0;
    req.on('data', chunk => {
      size += chunk.length;
      if (size > 4096) { req.destroy(); return; }
      body += chunk;
    });
    req.on('end', async () => {
      try {
        const { username, password } = JSON.parse(body);
        if (typeof username !== 'string' || typeof password !== 'string') {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'bad_request' }));
          return;
        }
        const user = users.get(username);
        if (!user) {
          // Constant-time: still do a hash comparison to prevent user enumeration
          await scryptAsync(password, crypto.randomBytes(16), 64);
          res.writeHead(401, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'invalid_credentials' }));
          return;
        }
        if (await verifyPassword(password, user.passwordHash)) {
          const token = tokenService.generateToken(username, ['read', 'write']);
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ token }));
        } else {
          res.writeHead(401, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'invalid_credentials' }));
        }
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'bad_request' }));
      }
    });
  } else if (req.method === 'GET' && url.pathname === '/api/data') {
    const authHeader = req.headers['authorization'];
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'missing_token' }));
      return;
    }

    const token = authHeader.slice(7);
    const result = tokenService.verifyToken(token);

    if (!result.valid) {
      res.writeHead(401, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'invalid_token' }));
      return;
    }

    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ data: 'sensitive_info', user: result.payload.sub }));
  } else if (req.method === 'POST' && url.pathname === '/auth/verify') {
    let body = '';
    let size = 0;
    req.on('data', chunk => {
      size += chunk.length;
      if (size > 8192) { req.destroy(); return; }
      body += chunk;
    });
    req.on('end', () => {
      try {
        const { token } = JSON.parse(body);
        if (typeof token !== 'string') {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'bad_request' }));
          return;
        }
        const result = tokenService.verifyToken(token);

        res.writeHead(result.valid ? 200 : 401, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          valid: result.valid,
          ...(result.valid ? { payload: result.payload } : { error: 'invalid_token' })
        }));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'bad_request' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'not_found' }));
  }
});

server.listen(process.env.PORT || 3000);
